    //     the page and in formatCompletionMessage; performance is a stable id
    //   - Spanish with accents; option texts true to the model and of similar length;
    //     labels repaint on a language switch without rebuilding the controls
    // ---------------------------------------------------------------

    class CircularEconomyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Circular Economy Factory';
            this.version = '1.3.0';

            this.BASE_TAKEBACK = 8;        // structural take-back rate at start
            this.RAMP_RATE = 0.10;         // quarterly adoption ramp on installed collection network
            this.CAPEX_DRAG = 0.3;         // margin points lost per $1M invested, current quarter only

            this.ROUNDS = [
                {
                    title_en: 'Q1 — Diagnose & Prioritize',
                    title_es: 'Q1 — Diagnosticar y Priorizar',
                    maxBudget: 15,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 12, circMaterial: 3, customer: 2, carbon: -2 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 8, investor: 5, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 10, circRevenue: 3.5, ebitda: 0.8, circMaterial: 1.5 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 15, circMaterial: 2, investor: 3 } },
                        { id: 'modularDesign', cost: 4.5, effects: { refurb: 5, carbon: -3, orgAlign: -5 }, delayedRefurbBonus: 0.22 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 20, investor: 2 } }
                    ],
                    hasSpecialDecision: false
                },
                {
                    title_en: 'Q2 — Build the Infrastructure',
                    title_es: 'Q2 — Construir la Infraestructura',
                    maxBudget: 18,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 10, circMaterial: 2, customer: 2, carbon: -2 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 6, investor: 3, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 8, circRevenue: 2.5, ebitda: 0.6, circMaterial: 1.2 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 10, circMaterial: 1, investor: 2 } },
                        { id: 'modularDesign', cost: 4.5, effects: { refurb: 3, carbon: -2, orgAlign: -3 }, delayedRefurbBonus: 0.15 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 12, investor: 1 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'telcomax'
                },
                {
                    title_en: 'Q3 — Scale & Integrate',
                    title_es: 'Q3 — Escalar e Integrar',
                    maxBudget: 20,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 8, circMaterial: 2, carbon: -1 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 5, investor: 2, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 6, circRevenue: 2, ebitda: 0.5, circMaterial: 1.0 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 8, circMaterial: 1 } },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 8 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'organizational'
                },
                {
                    title_en: 'Q4 — Measure, Report & Defend',
                    title_es: 'Q4 — Medir, Reportar y Defender',
                    maxBudget: 10,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 5, carbon: -1 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 4, customer: 1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 4, circRevenue: 1.5, circMaterial: 0.8 }, requiresTakeBack: 15 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 5 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'boardDefense'
                }
            ];

            this.CRISIS_EVENTS = [
                { id: 'contamination', effects: { takeBack: -4, investor: -8, customer: -3 } },
                { id: 'supplierDisruption', effects: { circMaterial: -3, carbon: 4, orgAlign: -5 } },
                { id: 'regulatoryAudit', effects: { regulatory: -10, investor: -5 } },
                { id: 'competitorLaunch', effects: { customer: -6, investor: -4 } },
                { id: 'mediaScandal', effects: { investor: -10, customer: -5 } },
                { id: 'workerStrike', effects: { orgAlign: -12, refurb: -5 } }
            ];

            this.TELCOMAX_COST = 6.2;
            this._periodsRun = 0;   // guards the undo-to-Q1 reseed (see initialize)
        }

        // ----------------------------------------------------------
        // Lifecycle
        // ----------------------------------------------------------
        _seedDomainState() {
            return {
                takeBack: 8,
                refurb: 2,
                ebitda: 9.2,
                ebitdaBase: 9.2,          // structural margin; capex drag is applied per-quarter, not compounded
                circRevenue: 0,
                carbon: 48,
                circMaterial: 0.3,
                regulatory: 12,
                investor: 42,
                customer: 71,
                orgAlign: 55,
                capitalAvailable: 42,
                capitalSpent: 0,
                score: 0,
                performance: { overallScore: 0, grade: 'Needs Improvement' },
                telcomaxAccepted: false,
                renewedLaunched: false,
                modularInvested: false,
                modularBonus: 0,
                crisisOccurred: false,
                crisisId: null,
                crisisPeriod: null,
                orgResponse: null,
                boardNarrative: null,
                investmentLog: [],
                ebitdaHistory: [],
                circRevenueHistory: [],
                takeBackHistory: [],
                carbonHistory: [],
                regulatoryHistory: [],
                investorHistory: [],
                customerHistory: [],
                orgAlignHistory: [],
                refurbHistory: [],
                circMaterialHistory: []
            };
        }

        initialize(state) {
            var isEmpty = !state.domainState || Object.keys(state.domainState).length === 0;
            var historyEmpty = !state.history || state.history.length === 0;

            // Fresh game, or undo back past Q1 (framework pops history to zero and
            // re-calls initialize but does NOT reset domainState itself).
            if (isEmpty || (historyEmpty && this._periodsRun > 0)) {
                state.domainState = this._seedDomainState();
                state.decisions = { selectedInvestments: [], totalSpent: 0, specialChoice: null };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedInvestments: [], totalSpent: 0, specialChoice: null };
            }
            // Back-fill for records saved by v1.0.0 (no ebitdaBase).
            if (state.domainState && typeof state.domainState.ebitdaBase !== 'number') {
                state.domainState.ebitdaBase = state.domainState.ebitda;
            }

            this._syncUI(state);
        }

        setupUI(uiManager) {
            var self = this;
            var n = function(v, d) { return self._num(v, d); };
            uiManager.bind('currentDay', 'currentPeriod', function(v) { return String(Math.min(Number(v) || 1, self.ROUNDS.length)); });
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('periodBadge', 'currentPeriod', function(v) { return 'Q' + Math.min(Number(v) || 1, self.ROUNDS.length); });
            uiManager.bind('takeBackDisplay', 'domainState.takeBack', function(v) { return n(v, 0) + '%'; });
            uiManager.bind('refurbDisplay', 'domainState.refurb', function(v) { return n(v, 0) + '%'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitda', function(v) { return n(v, 1) + '%'; });
            uiManager.bind('circRevenueDisplay', 'domainState.circRevenue', function(v) { return '$' + n(v, 1) + 'M'; });
            uiManager.bind('carbonDisplay', 'domainState.carbon', function(v) { return n(v, 0) + ' kg'; });
            uiManager.bind('circMaterialDisplay', 'domainState.circMaterial', function(v) { return n(v, 1) + '%'; });
            uiManager.bind('regulatoryDisplay', 'domainState.regulatory', function(v) { return n(v, 0) + '/100'; });
            uiManager.bind('investorDisplay', 'domainState.investor', function(v) { return n(v, 0) + '/100'; });
            uiManager.bind('customerDisplay', 'domainState.customer', function(v) { return n(v, 0) + '/100'; });
            uiManager.bind('orgAlignDisplay', 'domainState.orgAlign', function(v) { return n(v, 0) + '/100'; });

            // Re-render briefing / decisions from the framework lifecycle instead of a
            // setTimeout inside calculateResults (which fired after the framework had
            // already advanced the period, and also ran during competition preview).
            // period:submitted covers runtimes without a periodManager (the Open player),
            // and the final quarter, after which the platform runs no afterAdvance hook.
            var sim = window.mySimulation;
            var current = function(st) {
                var f = window.mySimulation;
                return (f && f.state && f.state.domainState) ? f.state : st;
            };
            if (sim && sim.periodManager && typeof sim.periodManager.addHook === 'function') {
                sim.periodManager.addHook('afterAdvance', function(st) { self._syncUI(st); });
            }
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('period:undone', function(st) { self._syncUI(current(st)); });
                sim.eventBus.on('period:submitted', function() { self._syncUI(current(null)); });
            }
            document.addEventListener('express:langchanged', function() {
                try { self._onLanguage(current(null)); } catch (e) { /* never break the page */ }
            });
        }

        // ----------------------------------------------------------
        // Decisions
        // ----------------------------------------------------------
        validateDecisions(decisions) {
            var state = (window.mySimulation && window.mySimulation.state) || { currentPeriod: 1, domainState: {} };
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var ds = state.domainState || {};
            var selected = [];
            var totalCost = 0;

            var checkboxes = document.querySelectorAll('.circular-sim-inv-check:checked');
            for (var i = 0; i < checkboxes.length; i++) {
                var cb = checkboxes[i];
                selected.push(cb.getAttribute('data-inv-id'));
                totalCost += parseFloat(cb.getAttribute('data-inv-cost'));
            }

            var specialChoice = null;
            if (round.hasSpecialDecision) {
                if (round.specialType === 'telcomax') {
                    var telcoRadio = document.querySelector('input[name="telcomaxBid"]:checked');
                    specialChoice = telcoRadio ? telcoRadio.value : 'decline';
                } else if (round.specialType === 'organizational') {
                    var orgRadio = document.querySelector('input[name="orgResponse"]:checked');
                    specialChoice = orgRadio ? orgRadio.value : 'engage';
                } else if (round.specialType === 'boardDefense') {
                    var boardRadio = document.querySelector('input[name="boardNarrative"]:checked');
                    specialChoice = boardRadio ? boardRadio.value : 'transparent';
                }
            }

            var committed = totalCost + (specialChoice === 'accept' ? this.TELCOMAX_COST : 0);

            if (totalCost > round.maxBudget) {
                this._notify('budget_exceeded', 'warning');
                return false;
            }

            // Cumulative capital envelope — declared in domainState but never enforced in v1.0.0.
            var available = (typeof ds.capitalAvailable === 'number') ? ds.capitalAvailable : 42;
            var spent = (typeof ds.capitalSpent === 'number') ? ds.capitalSpent : 0;
            var remaining = available - spent;
            if (committed > remaining + 1e-9) {
                this._notify('capital_exceeded', 'warning');
                return false;
            }

            decisions.selectedInvestments = selected;
            decisions.totalSpent = totalCost;
            decisions.specialChoice = specialChoice;
            return true;
        }

        // ----------------------------------------------------------
        // Model (pure: no DOM writes, no Math.random)
        // ----------------------------------------------------------
        calculateResults(state) {
            var d = state.decisions || {};
            var ds = state.domainState;
            var period = state.currentPeriod || 1;
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var selected = d.selectedInvestments || [];
            var periodCost = d.totalSpent || 0;
            var takeBackAtStart = ds.takeBack;   // gate is evaluated on the ENTERING collection rate
            var feedstockShort = false;

            for (var i = 0; i < selected.length; i++) {
                var invId = selected[i];
                var inv = null;
                for (var j = 0; j < round.investments.length; j++) {
                    if (round.investments[j].id === invId) { inv = round.investments[j]; break; }
                }
                if (!inv) continue;

                if (inv.requiresTakeBack && takeBackAtStart < inv.requiresTakeBack) {
                    var reduced = {};
                    for (var key in inv.effects) { reduced[key] = inv.effects[key] * 0.4; }
                    this._applyEffects(ds, reduced);
                    ds.investmentLog.push(invId + '_reduced');
                    feedstockShort = true;
                } else {
                    this._applyEffects(ds, inv.effects);
                    ds.investmentLog.push(invId);
                }

                if (invId === 'modularDesign') {
                    ds.modularInvested = true;
                    ds.modularBonus = Math.max(ds.modularBonus || 0, inv.delayedRefurbBonus || 0);
                }
            }

            // Q2: crisis event (deterministic per team) + TelcoMax PaaS bid
            var crisisIdThisPeriod = null;
            if (roundIdx === 1) {
                var crisis = this.CRISIS_EVENTS[this._crisisIndex(state)];
                ds.crisisOccurred = true;
                ds.crisisId = crisis.id;
                ds.crisisPeriod = period;
                crisisIdThisPeriod = crisis.id;
                this._applyEffects(ds, crisis.effects);

                if (d.specialChoice === 'accept') {
                    ds.telcomaxAccepted = true;
                    ds.circRevenue += 8.5;
                    ds.ebitdaBase += 1.5;
                    ds.investor += 10;
                    ds.customer += 5;
                    periodCost += this.TELCOMAX_COST;
                }
            }

            // Q3: organisational resistance
            if (roundIdx === 2 && d.specialChoice) {
                ds.orgResponse = d.specialChoice;
                if (d.specialChoice === 'restructure') {
                    ds.orgAlign += 18;
                    ds.ebitdaBase -= 0.8;
                    ds.customer += 3;
                } else if (d.specialChoice === 'engage') {
                    ds.orgAlign += 10;
                    ds.customer += 1;
                } else if (d.specialChoice === 'defer') {
                    ds.orgAlign -= 5;
                    ds.refurb -= 3;
                }
            }

            // Q4: payoffs and board narrative
            if (roundIdx === 3) {
                ds.boardNarrative = d.specialChoice || 'transparent';
                if (ds.regulatory >= 80) { ds.investor += 15; ds.customer += 5; }
                if (ds.takeBack >= 65) { ds.investor += 10; }
                if (ds.telcomaxAccepted) { ds.circRevenue += 4; ds.customer += 3; }
                if (ds.modularInvested) {
                    // delayedRefurbBonus was dead data in v1.0.0; it now drives the payoff.
                    var bonus = ds.modularBonus || 0.22;
                    ds.refurb += Math.round(bonus * 100 * 0.36 * 10) / 10;  // 0.22 -> ~7.9 pts of refurb rate
                    ds.ebitdaBase += bonus * 5.45;                          // 0.22 -> ~1.2 margin points
                }
                if (d.specialChoice === 'forward') { ds.investor += 8; }
                else if (d.specialChoice === 'transparent') { ds.investor += 5; }
                else { ds.investor += 2; }
            }

            // Collection-network adoption ramp: an installed network keeps recruiting
            // consumers quarter after quarter. Without this the EU 65% target was
            // mathematically unreachable (structural max was 57%).
            var ramp = 0;
            if (period > 1) {
                ramp = Math.max(0, ds.takeBack - this.BASE_TAKEBACK) * this.RAMP_RATE;
                ds.takeBack += ramp;
            }

            // Capital
            ds.capitalSpent += periodCost;

            // EBITDA: structural margin minus the capex drag of THIS quarter (v1.0.0 subtracted
            // the drag from the running margin, so it compounded and the margin could only fall).
            var investmentDrag = periodCost * this.CAPEX_DRAG;
            ds.ebitdaBase = Math.min(25, Math.max(-5, ds.ebitdaBase));
            ds.ebitda = Math.min(25, Math.max(-5, ds.ebitdaBase - investmentDrag));

            ds.takeBack = Math.min(100, Math.max(0, ds.takeBack));
            ds.refurb = Math.min(100, Math.max(0, ds.refurb));
            ds.circRevenue = Math.max(0, ds.circRevenue);
            ds.carbon = Math.max(10, Math.min(60, ds.carbon));
            ds.circMaterial = Math.min(100, Math.max(0, ds.circMaterial));
            ds.regulatory = Math.min(100, Math.max(0, ds.regulatory));
            ds.investor = Math.min(100, Math.max(0, ds.investor));
            ds.customer = Math.min(100, Math.max(0, ds.customer));
            ds.orgAlign = Math.min(100, Math.max(0, ds.orgAlign));

            ds.ebitdaHistory.push(parseFloat(ds.ebitda.toFixed(1)));
            ds.circRevenueHistory.push(parseFloat(ds.circRevenue.toFixed(1)));
            ds.takeBackHistory.push(parseFloat(ds.takeBack.toFixed(1)));
            ds.carbonHistory.push(parseFloat(ds.carbon.toFixed(1)));
            ds.regulatoryHistory.push(parseFloat(ds.regulatory.toFixed(1)));
            ds.investorHistory.push(parseFloat(ds.investor.toFixed(1)));
            ds.customerHistory.push(parseFloat(ds.customer.toFixed(1)));
            ds.orgAlignHistory.push(parseFloat(ds.orgAlign.toFixed(1)));
            ds.refurbHistory.push(parseFloat(ds.refurb.toFixed(1)));
            ds.circMaterialHistory.push(parseFloat(ds.circMaterial.toFixed(1)));

            this._periodsRun++;

            var _r = {
                takeBack: ds.takeBack, refurb: ds.refurb, ebitda: ds.ebitda, circRevenue: ds.circRevenue,
                carbon: ds.carbon, regulatory: ds.regulatory, investor: ds.investor,
                customer: ds.customer, orgAlign: ds.orgAlign
            };
            var _p = this._scorePillars(_r, period);
            ds.performance = {
                overallScore: _p.totalScore, grade: _p.grade,
                financialScore: _p.financialScore, envScore: _p.envScore, regScore: _p.regScore,
                stratScore: _p.stratScore, execScore: _p.execScore
            };
            ds.score = _p.totalScore;

            return {
                score: _p.totalScore,
                overallScore: _p.totalScore,
                grade: _p.grade,
                period: period,
                quarterLabel: 'Q' + period,
                investmentsChosen: selected.join(', ') || 'None',
                capitalInvested: periodCost,
                capitalRemaining: Math.max(0, ds.capitalAvailable - ds.capitalSpent),
                takeBack: ds.takeBack,
                takeBackRamp: parseFloat(ramp.toFixed(2)),
                refurb: ds.refurb,
                ebitda: ds.ebitda,
                circRevenue: ds.circRevenue,
                circMaterial: ds.circMaterial,
                carbon: ds.carbon,
                regulatory: ds.regulatory,
                investor: ds.investor,
                customer: ds.customer,
                orgAlign: ds.orgAlign,
                crisisId: crisisIdThisPeriod,
                feedstockShort: feedstockShort,
                specialChoice: d.specialChoice || null
            };
        }

        _applyEffects(ds, effects) {
            if (effects.takeBack) ds.takeBack += effects.takeBack;
            if (effects.refurb) ds.refurb += effects.refurb;
            if (effects.ebitda) ds.ebitdaBase += effects.ebitda;   // structural, not the displayed margin
            if (effects.circRevenue) ds.circRevenue += effects.circRevenue;
            if (effects.carbon) ds.carbon += effects.carbon;
            if (effects.circMaterial) ds.circMaterial += effects.circMaterial;
            if (effects.regulatory) ds.regulatory += effects.regulatory;
            if (effects.investor) ds.investor += effects.investor;
            if (effects.customer) ds.customer += effects.customer;
            if (effects.orgAlign) ds.orgAlign += effects.orgAlign;
        }

        // Deterministic crisis: same team always gets the same Q2 event, so the
        // competition-mode preview matches the submitted result and facilitators can
        // reproduce a run. (v1.0.0 rolled Math.random() inside calculateResults.)
        _crisisIndex(state) {
            var seedStr = String(state.gameId || '') + '|' + String(state.userId || '') + '|' + String(state.teamName || '');
            var h = 2166136261;
            for (var i = 0; i < seedStr.length; i++) {
                h ^= seedStr.charCodeAt(i);
                h = (h * 16777619) >>> 0;
            }
            return h % this.CRISIS_EVENTS.length;
        }

        // ----------------------------------------------------------
        // Charts / history / scoring
        // ----------------------------------------------------------
        // Opening values of the charted series: the first quarter then draws a line, not a dot.
        _chartStart() {
            var s = this._seedDomainState();
            return { ebitda: s.ebitda, circRevenue: s.circRevenue, takeBack: s.takeBack, carbon: s.carbon };
        }

        _chartText() {
            return {
                ebitda: this._t('chart_ebitda'), circRevenue: this._t('chart_circRevenue'),
                takeBack: this._t('chart_takeBack'), target: this._t('chart_target'), carbon: this._t('chart_carbon'),
                axisMargin: this._t('axis_margin'), axisRevenue: this._t('axis_revenue'),
                axisRate: this._t('axis_rate'), axisCarbon: this._t('axis_carbon')
            };
        }

        getChartConfig() {
            var self = this;
            var L = this._chartText();
            var still = false;
            try { still = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (e) { still = false; }
            var tick = function(d) { return function(v) { return self._num(v, d); }; };
            var common = function(scales) {
                return {
                    responsive: true,
                    maintainAspectRatio: false,
                    animation: still ? false : { duration: 400 },
                    interaction: { mode: 'index', intersect: false },
                    plugins: { legend: { position: 'bottom', labels: { boxWidth: 14, usePointStyle: true } } },
                    scales: scales
                };
            };
            return {
                financialChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: L.ebitda, data: [], yAxisID: 'y', borderColor: '#00695c', backgroundColor: '#00695c', borderWidth: 3, pointRadius: 4, pointStyle: 'circle', tension: 0, fill: false },
                            { label: L.circRevenue, data: [], yAxisID: 'y1', borderColor: '#e65100', backgroundColor: '#e65100', borderWidth: 3, borderDash: [6, 4], pointRadius: 5, pointStyle: 'rectRot', tension: 0, fill: false }
                        ]
                    },
                    options: common({
                        y: { position: 'left', beginAtZero: true, title: { display: true, text: L.axisMargin }, ticks: { callback: tick(0) } },
                        y1: { position: 'right', beginAtZero: true, title: { display: true, text: L.axisRevenue }, ticks: { callback: tick(0) }, grid: { drawOnChartArea: false } }
                    })
                },
                environmentalChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: L.takeBack, data: [], yAxisID: 'y', borderColor: '#2e7d32', backgroundColor: '#2e7d32', borderWidth: 3, pointRadius: 4, pointStyle: 'circle', tension: 0, fill: false },
                            { label: L.target, data: [], yAxisID: 'y', borderColor: '#757575', backgroundColor: '#757575', borderWidth: 2, borderDash: [2, 4], pointRadius: 0, fill: false },
                            { label: L.carbon, data: [], yAxisID: 'y1', borderColor: '#b71c1c', backgroundColor: '#b71c1c', borderWidth: 3, borderDash: [6, 4], pointRadius: 5, pointStyle: 'triangle', tension: 0, fill: false }
                        ]
                    },
                    options: common({
                        y: { position: 'left', beginAtZero: true, suggestedMax: 80, title: { display: true, text: L.axisRate }, ticks: { callback: tick(0) } },
                        y1: { position: 'right', beginAtZero: false, suggestedMin: 30, suggestedMax: 50, title: { display: true, text: L.axisCarbon }, ticks: { callback: tick(0) }, grid: { drawOnChartArea: false } }
                    })
                }
            };
        }

        // Tolerates a missing or partly restored domainState (EQIL defect family item 2).
        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var s = this._chartStart();
            var L = this._chartText();
            var h = function(k) { return Array.isArray(ds[k]) ? ds[k] : []; };
            var quarters = h('ebitdaHistory').length;
            var labels = [this._t('chart_start')];
            for (var i = 0; i < quarters; i++) labels.push('Q' + (i + 1));
            return {
                financialChart: {
                    labels: labels,
                    datasets: [
                        { label: L.ebitda, data: [s.ebitda].concat(h('ebitdaHistory')) },
                        { label: L.circRevenue, data: [s.circRevenue].concat(h('circRevenueHistory')) }
                    ]
                },
                environmentalChart: {
                    labels: labels,
                    datasets: [
                        { label: L.takeBack, data: [s.takeBack].concat(h('takeBackHistory')) },
                        { label: L.target, data: labels.map(function() { return 65; }) },
                        { label: L.carbon, data: [s.carbon].concat(h('carbonHistory')) }
                    ]
                }
            };
        }

        // Axis titles live in the chart options, which the frameworks build once: relabel in place.
        _relabelCharts() {
            if (typeof window.Chart === 'undefined' || typeof window.Chart.getChart !== 'function') return;
            var L = this._chartText();
            var spec = {
                financialChart: { names: [L.ebitda, L.circRevenue], y: L.axisMargin, y1: L.axisRevenue },
                environmentalChart: { names: [L.takeBack, L.target, L.carbon], y: L.axisRate, y1: L.axisCarbon }
            };
            Object.keys(spec).forEach(function(id) {
                var ch = null;
                try { ch = window.Chart.getChart(id); } catch (e) { ch = null; }
                if (!ch) return;
                var sp = spec[id];
                (ch.data.datasets || []).forEach(function(d, i) { if (sp.names[i]) d.label = sp.names[i]; });
                try {
                    if (ch.options.scales.y && ch.options.scales.y.title) ch.options.scales.y.title.text = sp.y;
                    if (ch.options.scales.y1 && ch.options.scales.y1.title) ch.options.scales.y1.title.text = sp.y1;
                } catch (e) { /* older config */ }
                try { ch.update('none'); } catch (e) { /* chart torn down */ }
            });
        }

        // Text alternative for both charts (WCAG 1.1.1): the latest values, in words.
        _renderChartSummaries(state) {
            var ds = (state && state.domainState) || {};
            var n = this;
            var q = Array.isArray(ds.ebitdaHistory) ? ds.ebitdaHistory.length : 0;
            var s = this._chartStart();
            var last = function(k, d) { var a = ds[k]; return (Array.isArray(a) && a.length) ? a[a.length - 1] : d; };
            var vals = {
                q: 'Q' + q,
                e: n._num(last('ebitdaHistory', s.ebitda), 1),
                r: '$' + n._num(last('circRevenueHistory', s.circRevenue), 1) + 'M',
                t: n._num(last('takeBackHistory', s.takeBack), 0),
                c: n._num(last('carbonHistory', s.carbon), 0)
            };
            var fin = document.getElementById('financialChartSummary');
            var env = document.getElementById('environmentalChartSummary');
            if (fin) fin.textContent = this._tf(q ? 'chart_fin_summary' : 'chart_fin_summary_start', vals);
            if (env) env.textContent = this._tf(q ? 'chart_env_summary' : 'chart_env_summary_start', vals);
        }

        // Five pillars, 100 points: Financial 25 / Environmental 20 / Regulatory 20 /
        // Strategic 20 / Execution 15. (v1.0.0 summed to a maximum of 110 while the
        // grade bands assumed a 100-point scale.)
        // Shared pillar calculator. express/results_utils.php :: express_resolveDomainScore()
        // reads domainState.performance.overallScore (or a top-level score), so the score
        // MUST be written into domainState every period or the instructor panel shows a dash
        // and the LTI grade is 0. v1.0.0 only computed it client-side at the very end.
        _scorePillars(r, periodsPlayed) {
            var financialScore = 5;
            if (r.ebitda >= 12) financialScore = 15;
            else if (r.ebitda >= 9) financialScore = 10;
            financialScore += Math.min(10, (r.circRevenue || 0) * 0.8);

            var envScore = 0;
            if (r.carbon <= 32) envScore = 10;
            else if (r.carbon <= 40) envScore = 6;
            envScore += Math.min(5, (r.takeBack || 0) * 0.08);
            envScore += Math.min(5, (r.refurb || 0) * 0.2);

            var regScore = 0;
            if (r.takeBack >= 65) regScore += 10;
            if (r.regulatory >= 80) regScore += 10;

            var stratScore = 0;
            if (r.customer >= 80) stratScore += 8;
            if (r.investor >= 70) stratScore += 8;
            stratScore += Math.min(4, (r.circRevenue || 0) * 0.3);

            var execScore = 0;
            if (r.orgAlign >= 70) execScore += 10;
            execScore += Math.min(5, (periodsPlayed || 1) * 1.25);

            var total = financialScore + envScore + regScore + stratScore + execScore;
            var grade = 'Needs Improvement';
            if (total >= 80) grade = 'Circular Leader';
            else if (total >= 60) grade = 'Strong Transformer';
            else if (total >= 40) grade = 'Emerging Circular';

            return {
                totalScore: Math.round(total),
                grade: grade,
                financialScore: Math.round(financialScore),
                envScore: Math.round(envScore),
                regScore: Math.round(regScore),
                stratScore: Math.round(stratScore),
                execScore: Math.round(execScore)
            };
        }


        // ----------------------------------------------------------
        // Debrief: verdict, turning point, named mistakes, questions
        // ----------------------------------------------------------
        _gradeId(grade) {
            // Stable, language-neutral ids; each is also the translation key of its label.
            if (grade === 'Circular Leader') return 'leader';
            if (grade === 'Strong Transformer') return 'strong';
            if (grade === 'Emerging Circular') return 'emerging';
            return 'needs';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var p = this._scorePillars(r, history.length);
            var id = this._gradeId(p.grade);
            var deb = this._debrief(history, p);
            return {
                totalPeriods: history.length,
                totalScore: p.totalScore,
                overallScore: p.totalScore,
                composite: p.totalScore,
                score: p.totalScore,
                performance: id,
                performanceKey: id,
                performanceLabel: this._t(id),
                financialScore: p.financialScore,
                envScore: p.envScore,
                regScore: p.regScore,
                stratScore: p.stratScore,
                execScore: p.execScore,
                turningPoint: deb.turningPoint,
                insights: deb.insights,
                discussionQuestions: deb.questions
            };
        }

        // Facts read from the run history only, so the debrief never describes a play
        // the student did not make (EQIL defect family item 13).
        _runFacts(history) {
            var qs = [];
            for (var i = 0; i < history.length; i++) {
                var h = history[i] || {};
                var r = h.results || {};
                var d = h.decisions || {};
                var sel = Array.isArray(d.selectedInvestments) ? d.selectedInvestments.slice()
                    : ((r.investmentsChosen && r.investmentsChosen !== 'None') ? String(r.investmentsChosen).split(/,\s*/) : []);
                qs.push({
                    n: Number(r.period) || (i + 1),
                    sel: sel,
                    spend: Number(r.capitalInvested) || 0,
                    special: r.specialChoice || d.specialChoice || null,
                    feedstockShort: !!r.feedstockShort,
                    crisisId: r.crisisId || null,
                    r: r
                });
            }
            return qs;
        }

        _debrief(history, p) {
            var self = this;
            var qs = this._runFacts(history);
            var fin = qs.length ? qs[qs.length - 1].r : {};
            var money = function(v) { return '$' + self._num(v, 1) + 'M'; };
            var has = function(q, id) { return !!q && q.sel.indexOf(id) >= 0; };
            var byN = function(k) { for (var i = 0; i < qs.length; i++) { if (qs[i].n === k) return qs[i]; } return null; };
            var q1 = byN(1), q2 = byN(2), q3 = byN(3), q4 = byN(4);
            var tb = Number(fin.takeBack) || 0;
            var reg = Number(fin.regulatory) || 0;
            var align = Number(fin.orgAlign) || 0;
            var mistakes = [];   // { w: weight for the turning point, q: quarter, text }
            var notes = [];      // threshold facts, positives and context, in this order

            if (q1 && !has(q1, 'reverseLogistics') && !has(q1, 'takeBackKiosks')) {
                mistakes.push({ w: 18, q: 1, key: 'noCollection', text: this._tf('ins_noCollection', {}) });
            }
            for (var i = 0; i < qs.length; i++) {
                if (qs[i].feedstockShort) {
                    mistakes.push({ w: 2, q: qs[i].n, key: 'feedstock', text: this._tf('ins_feedstock', { q: 'Q' + qs[i].n }) });
                    break;
                }
            }
            if (q2 && q2.special === 'decline') {
                mistakes.push({ w: 16, q: 2, key: 'telcoDeclined', text: this._tf('ins_telcoDeclined', { rev: money(fin.circRevenue), c: this._num(fin.customer, 0) }) });
            } else if (q2 && q2.special === 'accept') {
                notes.push(this._tf('ins_telcoAccepted', { rev: money(fin.circRevenue), c: this._num(fin.customer, 0) }));
            }
            if (q3 && q3.special === 'defer') {
                mistakes.push({ w: 11, q: 3, key: 'orgDefer', text: this._tf('ins_orgDefer', { a: this._num(align, 0) }) });
            } else if (q3 && q3.special && align < 70) {
                mistakes.push({ w: 10, q: 3, key: 'orgShort', text: this._tf(q3.special === 'restructure' ? 'ins_orgRestructureMiss' : 'ins_orgEngageMiss', { a: this._num(align, 0) }) });
            } else if (q3 && q3.special && align >= 70) {
                notes.push(this._tf('ins_orgCleared', { a: this._num(align, 0) }));
            }
            if (q4) {
                var drag = q4.spend * this.CAPEX_DRAG;
                var e1 = Number(fin.ebitda) || 0;
                var e0 = e1 + drag;
                var tier = null;
                if (e1 < 9 && e0 >= 9) tier = 9;
                else if (e1 < 12 && e0 >= 12) tier = 12;
                var left = Number(fin.capitalRemaining) || 0;
                if (tier !== null && drag > 0) {
                    mistakes.push({ w: 16, q: 4, key: 'q4Drag', text: this._tf('ins_q4Drag', { s: money(q4.spend), d: this._num(drag, 1), e0: this._num(e0, 1), e1: this._num(e1, 1), t: tier }) });
                }
                if (q4.spend < 2.8 && left >= 2.8 && tb < 65) {
                    mistakes.push({ w: 16, q: 4, key: 'heldBack', text: this._tf('ins_heldBack', { k: money(left), t: this._num(tb, 1) }) });
                }
            }
            var named = {};
            mistakes.forEach(function(m) { named[m.key] = true; });
            var missTb = (tb < 65 && !named.heldBack) ? this._tf('ins_takeBackMiss', { t: this._num(tb, 1) }) : null;
            var missReg = (reg < 80) ? this._tf('ins_complianceMiss', { c: this._num(reg, 0) }) : null;
            if (missTb) notes.unshift(missTb);
            else if (tb >= 65) notes.push(this._tf('ins_takeBackHit', { t: this._num(tb, 1) }));
            if (missReg) notes.unshift(missReg);
            else notes.push(this._tf('ins_complianceHit', { c: this._num(reg, 0) }));
            var crisis = null;
            for (var c = 0; c < qs.length; c++) { if (qs[c].crisisId) { crisis = qs[c].crisisId; break; } }
            if (crisis) notes.push(this._tf('ins_crisis', { e: this._t('crisis_name_' + crisis) }));

            // Turning point: the costliest mistake of this run (earliest on a tie); else what carried it.
            var turning;
            if (mistakes.length) {
                var top = mistakes.slice().sort(function(a, b) { return (b.w - a.w) || (a.q - b.q); })[0];
                turning = top.text;
                mistakes = mistakes.filter(function(m) { return m !== top; });
            } else if (q1 && (has(q1, 'reverseLogistics') || has(q1, 'takeBackKiosks')) && (has(q1, 'digitalPassport') || has(q1, 'eprSoftware')) && tb >= 65 && reg >= 80) {
                turning = this._tf('tp_quarter', { q: 'Q1' }) + ' ' + this._t('tp_goodStart');
            } else if (missTb || missReg) {
                turning = missTb || missReg;
                notes = notes.filter(function(t) { return t !== turning; });
            } else {
                turning = this._tf('tp_none', { s: p.totalScore });
            }
            mistakes.sort(function(a, b) { return a.q - b.q; });
            var insights = mistakes.map(function(m) { return m.text; }).concat(notes).slice(0, 5);
            return {
                turningPoint: turning,
                insights: insights,
                questions: [this._t('dq_1'), this._t('dq_2'), this._t('dq_3')]
            };
        }

        _esc(s) {
            return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        }

        _debriefHtml(summary) {
            var s = summary || {};
            var self = this;
            var e = function(v) { return self._esc(v); };
            var label = s.performance ? this._t(s.performance) : (s.performanceLabel || '');
            var html = '';
            html += '<p><span class="circular-sim-debrief-verdict">' + e(label) + '</span>'
                + '<span class="circular-sim-debrief-score">' + e(this._tf('debrief_score', { s: s.totalScore })) + '</span></p>';
            html += '<h4>' + e(this._t('debrief_turning')) + '</h4>';
            html += '<p class="circular-sim-debrief-turn">' + e(s.turningPoint || '') + '</p>';
            if (Array.isArray(s.insights) && s.insights.length) {
                html += '<h4>' + e(this._t('debrief_insights')) + '</h4><ul>';
                s.insights.forEach(function(t) { html += '<li>' + e(t) + '</li>'; });
                html += '</ul>';
            }
            html += '<h4>' + e(this._t('debrief_pillars')) + '</h4>';
            html += '<table><tbody>';
            [['pillar_fin', s.financialScore, 25], ['pillar_env', s.envScore, 20], ['pillar_reg', s.regScore, 20],
                ['pillar_str', s.stratScore, 20], ['pillar_exe', s.execScore, 15], ['pillar_total', s.totalScore, 100]].forEach(function(row) {
                html += '<tr><th scope="row">' + e(self._t(row[0])) + '</th><td class="num">' + e(row[1]) + ' / ' + row[2] + '</td></tr>';
            });
            html += '</tbody></table>';
            if (Array.isArray(s.discussionQuestions) && s.discussionQuestions.length) {
                html += '<h4>' + e(this._t('debrief_questions')) + '</h4><ol>';
                s.discussionQuestions.forEach(function(t) { html += '<li>' + e(t) + '</li>'; });
                html += '</ol>';
            }
            return html;
        }

        formatCompletionMessage(summary) {
            return '<div class="completion-message usf-debrief circular-sim-debrief-modal p-4">' + this._debriefHtml(summary) + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            // Crisis first: in v1.0.0 the generic hints masked the crisis message, so the
            // player never learned what had just hit their KPIs.
            if (results.crisisId) {
                return window.mySimulation.t('hint_crisis_' + results.crisisId);
            }
            if (results.feedstockShort) {
                return window.mySimulation.t('refurb_warning');
            }
            if (ds.takeBack < 20 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_lowTakeBack');
            }
            if (ds.regulatory < 40 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_lowRegulatory');
            }
            if (ds.ebitda < 5) {
                return window.mySimulation.t('hint_lowMargin');
            }
            if (ds.refurb < 10 && ds.takeBack > 30) {
                return window.mySimulation.t('hint_refurbGap');
            }
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            var n = function(v, d) { return self._num(v, d); };
            return [
                { key: 'results.quarterLabel', label: 'Quarter', i18nKey: 'col_quarter' },
                { key: 'results.investmentsChosen', label: 'Investments', i18nKey: 'col_investments', formatter: function(v) { return self._esc(self._investmentNames(v)); } },
                { key: 'results.capitalInvested', label: 'Capital ($M)', i18nKey: 'col_capital', formatter: function(v) { return '$' + n(v, 1) + 'M'; } },
                { key: 'results.takeBack', label: 'Take-Back %', i18nKey: 'col_takeBack', formatter: function(v) { return n(v, 0) + '%'; } },
                { key: 'results.ebitda', label: 'EBITDA %', i18nKey: 'col_ebitda', formatter: function(v) { return n(v, 1) + '%'; } },
                { key: 'results.circRevenue', label: 'Circular revenue', i18nKey: 'col_circRevenue', formatter: function(v) { return '$' + n(v, 1) + 'M'; } },
                { key: 'results.carbon', label: 'Carbon', i18nKey: 'col_carbon', formatter: function(v) { return n(v, 0) + ' kg'; } },
                { key: 'results.regulatory', label: 'Compliance', i18nKey: 'col_regulatory', formatter: function(v) { return n(v, 0) + '/100'; } },
                { key: 'results.investor', label: 'Investor', i18nKey: 'col_investor', formatter: function(v) { return n(v, 0) + '/100'; } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score', formatter: function(v) { return n(v, 0); } }
            ];
        }

        // History rows store investment ids (results.investmentsChosen); show their names.
        _investmentNames(v) {
            var self = this;
            if (!v || v === 'None') return this._t('inv_none');
            return String(v).split(/,\s*/).map(function(id) { return self._t('short_' + id); }).join(', ');
        }

        getPresets() { return null; }

        // ----------------------------------------------------------
        // UI rendering (all DOM writes live here, never in calculateResults)
        // ----------------------------------------------------------
        _notify(key, type) {
            try {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t(key), type || 'info');
            } catch (e) { /* preview / headless */ }
        }

        _t(key) {
            try { return window.mySimulation.t(key); } catch (e) { return key; }
        }

        _tf(key, vars) {
            var s = String(this._t(key));
            Object.keys(vars || {}).forEach(function(k) { s = s.split('{' + k + '}').join(String(vars[k])); });
            return s;
        }

        // Language of the session: vcI18n on the platform, the framework language elsewhere.
        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return String(window.vcI18n._lang).slice(0, 2).toLowerCase(); } catch (e) { /* none */ }
            try { if (window.mySimulation && window.mySimulation.lang) return String(window.mySimulation.lang).slice(0, 2).toLowerCase(); } catch (e) { /* none */ }
            return String(document.documentElement.lang || 'en').slice(0, 2).toLowerCase();
        }

        // Fixed decimals with the decimal comma in Spanish.
        _num(v, d) {
            var x = Number(v);
            if (!isFinite(x)) x = 0;
            var s = x.toFixed(d);
            if (/^-0(\.0+)?$/.test(s)) s = s.slice(1);
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        _history() {
            var f = window.mySimulation;
            if (f && f.state && Array.isArray(f.state.history)) return f.state.history;
            if (f && Array.isArray(f.history)) return f.history;
            return [];
        }

        _isComplete(state) {
            var ds = (state && state.domainState) || {};
            return Array.isArray(ds.ebitdaHistory) && ds.ebitdaHistory.length >= this.ROUNDS.length;
        }

        _syncUI(state) {
            if (!state) return;
            var done = this._isComplete(state);
            this._updateBriefing(state);
            var area = document.getElementById('decisionArea');
            var submit = document.getElementById('nextPeriodBtn');
            if (done) {
                var panel = document.getElementById('decisionPanel');
                if (panel) panel.innerHTML = '';
                if (area) { area.hidden = true; area.style.display = 'none'; }
                if (submit) submit.style.display = 'none';
            } else {
                if (area) { area.hidden = false; area.style.display = ''; }
                if (submit) submit.style.display = '';
                this._buildDecisionPanel(state);
            }
            this._renderEventCard(state);
            this._renderChartSummaries(state);
            this._renderDebrief(state);
        }

        _renderDebrief(state) {
            var box = document.getElementById('debriefPanel');
            var body = document.getElementById('debriefBody');
            if (!box || !body) return;
            var hist = this._history();
            if (this._isComplete(state) && hist.length >= this.ROUNDS.length) {
                body.innerHTML = this._debriefHtml(this.getPerformanceSummary(hist));
                box.hidden = false;
                box.style.display = '';
            } else {
                body.innerHTML = '';
                box.hidden = true;
                box.style.display = 'none';
            }
        }

        // express:langchanged: repaint what the adapter wrote, keep the controls and their state.
        _onLanguage(state) {
            if (!state) return;
            this._updateBriefing(state);
            this._renderEventCard(state);
            this._renderChartSummaries(state);
            this._renderDebrief(state);
            var costs = document.querySelectorAll('.circular-sim-inv-cost[data-cost]');
            for (var i = 0; i < costs.length; i++) {
                costs[i].textContent = '$' + this._num(parseFloat(costs[i].getAttribute('data-cost')), 1) + 'M';
            }
            if (typeof this._recalc === 'function') this._recalc();
            this._relabelCharts();
            var f = window.mySimulation;
            try { if (f && typeof f.updateUI === 'function') f.updateUI(); } catch (e) { /* framework variant */ }
        }

        _updateBriefing(state) {
            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;
            if (this._isComplete(state)) { briefEl.innerHTML = this._t('brief_done'); return; }
            var period = Math.min(Math.max(state.currentPeriod || 1, 1), 4);
            var keys = ['brief_q1', 'brief_q2', 'brief_q3', 'brief_q4'];
            briefEl.innerHTML = this._t(keys[period - 1]);
        }

        _renderEventCard(state) {
            var card = document.getElementById('eventCard');
            if (!card) return;
            var ds = state.domainState || {};
            var title = document.getElementById('eventCardTitle');
            var body = document.getElementById('eventCardBody');
            if (ds.crisisId && ds.crisisPeriod && (state.currentPeriod || 1) > ds.crisisPeriod) {
                if (title) title.textContent = this._t('crisis_title') + ' — Q' + ds.crisisPeriod;
                if (body) body.innerHTML = this._t('hint_crisis_' + ds.crisisId);
                card.style.display = '';
                card.hidden = false;
            } else {
                card.style.display = 'none';
                card.hidden = true;
            }
        }

        // Same two checks as validateDecisions: the quarterly cap counts the tickets only, the
        // programme envelope counts the tickets plus any TelcoMax commitment. (v1.2.0 tested the cap
        // against both, so accepting TelcoMax disabled a submission the validator accepts.)
        _renderCapital(state, round, total, committed) {
            if (typeof committed !== 'number') committed = total;
            var ds = state.domainState || {};
            var remaining = (ds.capitalAvailable || 0) - (ds.capitalSpent || 0);
            var el = document.getElementById('capitalRemaining');
            if (el) {
                el.textContent = this._t('capital_remaining') + ' $' + this._num(Math.max(0, remaining), 1) + 'M / $'
                    + this._num(ds.capitalAvailable || 0, 0) + 'M';
            }
            var err = document.getElementById('budgetError');
            var submitBtn = document.getElementById('nextPeriodBtn');
            var over = null;
            if (total > round.maxBudget + 1e-9) over = 'budget_exceeded';
            else if (committed > remaining + 1e-9) over = 'capital_exceeded';
            if (err) {
                if (over) { err.textContent = this._t(over); err.hidden = false; err.style.display = ''; }
                else { err.textContent = ''; err.hidden = true; err.style.display = 'none'; }
            }
            if (submitBtn) {
                submitBtn.disabled = !!over;
                if (over) submitBtn.setAttribute('aria-disabled', 'true');
                else submitBtn.removeAttribute('aria-disabled');
            }
        }

        // One radio decision. Option texts sit in data-i18n spans, so a language switch
        // relabels them without rebuilding the inputs (and without losing the choice).
        _radioGroup(name, prefix, values, withDesc) {
            var h = '<fieldset class="circular-sim-radio-group circular-sim-radio-' + prefix + '">';
            h += '<legend data-i18n="' + prefix + '_title">' + this._t(prefix + '_title') + '</legend>';
            h += '<p data-i18n="' + prefix + '_desc">' + this._t(prefix + '_desc') + '</p>';
            for (var i = 0; i < values.length; i++) {
                var v = values[i];
                var id = name + '_' + v;
                h += '<div class="circular-sim-radio-option">';
                h += '<label for="' + id + '"><input type="radio" name="' + name + '" id="' + id + '" value="' + v + '"'
                    + (withDesc ? ' aria-describedby="' + id + '_desc"' : '') + '> '
                    + '<span data-i18n="' + prefix + '_' + v + '">' + this._t(prefix + '_' + v) + '</span></label>';
                if (withDesc) {
                    h += '<div class="circular-sim-inv-desc" id="' + id + '_desc" data-i18n="' + prefix + '_' + v + '_desc">'
                        + this._t(prefix + '_' + v + '_desc') + '</div>';
                }
                h += '</div>';
            }
            h += '</fieldset>';
            return h;
        }

        _buildDecisionPanel(state) {
            var period = Math.min(Math.max(state.currentPeriod || 1, 1), 4);
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var panel = document.getElementById('decisionPanel');
            if (!panel) return;

            var self = this;
            var html = '';

            for (var i = 0; i < round.investments.length; i++) {
                var inv = round.investments[i];
                var descId = 'invdesc_' + inv.id;
                html += '<div class="circular-sim-inv-option">';
                html += '<input type="checkbox" class="circular-sim-inv-check" data-inv-id="' + inv.id + '" data-inv-cost="' + inv.cost + '" id="inv_' + inv.id + '" aria-describedby="' + descId + '">';
                html += '<label for="inv_' + inv.id + '" data-i18n="inv_' + inv.id + '">' + this._t('inv_' + inv.id) + '</label>';
                html += '<span class="circular-sim-inv-cost" data-cost="' + inv.cost + '">$' + this._num(inv.cost, 1) + 'M</span>';
                html += '</div>';
                html += '<div class="circular-sim-inv-desc" id="' + descId + '" data-i18n="inv_' + inv.id + '_desc">' + this._t('inv_' + inv.id + '_desc') + '</div>';
            }

            if (round.hasSpecialDecision && round.specialType === 'telcomax') {
                html += this._radioGroup('telcomaxBid', 'telcomax', ['accept', 'decline'], false);
            }
            if (round.hasSpecialDecision && round.specialType === 'organizational') {
                html += this._radioGroup('orgResponse', 'org', ['restructure', 'engage', 'defer'], true);
            }
            if (round.hasSpecialDecision && round.specialType === 'boardDefense') {
                html += this._radioGroup('boardNarrative', 'board', ['forward', 'transparent', 'defensive'], false);
            }

            panel.innerHTML = html;

            var budgetDisplay = document.getElementById('budgetDisplay');
            var budgetFill = document.getElementById('budgetFill');
            var budgetTrack = document.getElementById('budgetTrack');
            if (budgetTrack) budgetTrack.setAttribute('aria-valuemax', String(round.maxBudget));

            function recalc() {
                var total = 0;
                var selected = panel.querySelectorAll('.circular-sim-inv-check:checked');
                for (var s = 0; s < selected.length; s++) {
                    total += parseFloat(selected[s].getAttribute('data-inv-cost'));
                }
                var telco = document.querySelector('input[name="telcomaxBid"]:checked');
                var committed = total + (telco && telco.value === 'accept' ? self.TELCOMAX_COST : 0);

                if (budgetDisplay) budgetDisplay.textContent = '$' + self._num(total, 1) + 'M / $' + self._num(round.maxBudget, 0) + 'M';
                if (budgetTrack) {
                    budgetTrack.setAttribute('aria-valuenow', self._num(total, 1).replace(',', '.'));
                    budgetTrack.setAttribute('aria-valuetext', '$' + self._num(total, 1) + 'M / $' + self._num(round.maxBudget, 0) + 'M');
                }
                if (budgetFill) {
                    budgetFill.style.width = Math.min(100, (total / round.maxBudget) * 100) + '%';
                    budgetFill.style.background = (total > round.maxBudget)
                        ? 'linear-gradient(90deg, #f44336, #e53935)'
                        : 'linear-gradient(90deg, #00897b, #4caf50)';
                }
                self._renderCapital(state, round, total, committed);
            }
            this._recalc = recalc;

            var checks = panel.querySelectorAll('.circular-sim-inv-check');
            for (var c = 0; c < checks.length; c++) {
                checks[c].addEventListener('change', recalc);
            }
            var radios = panel.querySelectorAll('input[type="radio"]');
            for (var rr = 0; rr < radios.length; rr++) {
                radios[rr].addEventListener('change', recalc);
            }

            recalc();
        }

